ALIASES = {
    "getShipments": "getShipmentsV0",
}

def resolve_op(name: str) -> dict:
    key = ALIASES.get(name, name)
    if key not in OPERATIONS:
        raise KeyError(f"Unknown FBA operation: {name}")
    return OPERATIONS[key]
